#include <cstdio>
#include <cstdlib>
#include <memory>

int c_make(int** out) {
  std::puts("c_make");
  *out = static_cast<int*>(std::malloc(sizeof(int)));
  **out = 7;
  return 0;
}

struct Free {
  void operator()(int* p) const { std::puts("free"); std::free(p); }
};

int main() {
  std::unique_ptr<int, Free> p(static_cast<int*>(std::malloc(sizeof(int))));
  c_make(std::out_ptr(p));
  std::printf("%d\n", *p);
}
